SELECT b.billing_id AS billingId, b.patient_id AS patientId, b.visit_id AS visitId, b.admission_id AS admissionId, b.billing_status AS billingStatus, b.created_at AS createdAt, b.updated_at AS updatedAt
FROM billing b
WHERE 1 = 1
AND b.patient_id = #{patientId}
AND b.visit_id = #{visitId}
AND b.admission_id = #{admissionId}
AND b.billing_status = #{billingStatus}
ORDER BY b.created_at DESC

SELECT b.billing_id AS billingId, b.billing_status AS billingStatus
FROM billing b
WHERE b.billing_id = #{billingId}
